-- Os textos da página da newsletter. Sem linha na base, a página mostra
-- as omissões do código, mas o backoffice só edita linhas que existem:
-- é isto que os torna editáveis na produção. INSERT OR IGNORE não toca
-- numa linha que alguém já tenha criado.
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('6ffcbdea-a764-4bfa-afc1-dd895c163840', 'newsletter.descricao', '{"pt":"Subscreva a newsletter da Galeria Contagiarte e saiba primeiro das exposições, das obras novas e das inaugurações.","en":"Subscribe to the Galeria Contagiarte newsletter and be the first to hear about exhibitions, new works and openings.","es":"Suscríbase a la newsletter de la Galería Contagiarte y sepa primero de las exposiciones, las obras nuevas y las inauguraciones."}', 'Descrição da página da newsletter nos motores de busca e nos cartões de partilha.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('c332df04-f6bc-46bb-b2c3-077bb67de851', 'newsletter.pagina.titulo', '{"pt":"SAIBA ANTES DE TODOS.","en":"HEAR IT BEFORE ANYONE.","es":"SÉPALO ANTES QUE NADIE."}', 'Título grande da página da newsletter.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('4f37231c-83e7-4f2d-86a4-86b4469f9f05', 'newsletter.pagina.intro', '{"pt":"As novidades da galeria chegam primeiro a quem subscreve, por email: o que vamos expor, as obras que entram e os convites para as inaugurações.","en":"Gallery news reaches subscribers first, by email: what we are about to show, the works coming in and the invitations to openings.","es":"Las novedades de la galería llegan primero a quien se suscribe, por email: lo que vamos a exponer, las obras que entran y las invitaciones a las inauguraciones."}', 'Frase de abertura da página da newsletter, por baixo do título.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('69db36b8-7008-4904-8a37-749500db97fe', 'newsletter.vantagem.1.titulo', '{"pt":"Exposições novas","en":"New exhibitions","es":"Exposiciones nuevas"}', 'Página da newsletter: título da primeira vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('82f48527-2d1a-45a1-8a40-13a212c935e9', 'newsletter.vantagem.1.texto', '{"pt":"A data, o lugar e os artistas, antes de a exposição abrir.","en":"The date, the place and the artists, before the exhibition opens.","es":"La fecha, el lugar y los artistas, antes de que abra la exposición."}', 'Página da newsletter: texto da primeira vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('93d53081-4aae-4fa1-94ec-11ba0172ae88', 'newsletter.vantagem.2.titulo', '{"pt":"Obras que entram","en":"Works coming in","es":"Obras que entran"}', 'Página da newsletter: título da segunda vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('892b94ea-43fd-48d2-8c7d-d0077f8c01dc', 'newsletter.vantagem.2.texto', '{"pt":"As obras que chegam à galeria, com imagem e medidas, assim que chegam.","en":"The works arriving at the gallery, with image and dimensions, as soon as they arrive.","es":"Las obras que llegan a la galería, con imagen y medidas, en cuanto llegan."}', 'Página da newsletter: texto da segunda vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('8439ee75-d11f-481f-aac6-c4c3755b34c8', 'newsletter.vantagem.3.titulo', '{"pt":"Inaugurações","en":"Openings","es":"Inauguraciones"}', 'Página da newsletter: título da terceira vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('1aae5c45-7ddd-4e91-878b-52382a1e7eb9', 'newsletter.vantagem.3.texto', '{"pt":"O convite para cada inauguração, com tempo para a pôr na agenda.","en":"An invitation to each opening, with time to put it in the diary.","es":"La invitación a cada inauguración, con tiempo para apuntarla en la agenda."}', 'Página da newsletter: texto da terceira vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('93672dfa-94b1-45df-a56d-0341601b284b', 'newsletter.vantagem.4.titulo', '{"pt":"Condições reservadas","en":"Subscriber terms","es":"Condiciones reservadas"}', 'Página da newsletter: título da quarta vantagem.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('fb0a9c66-8124-42d0-9aba-053903c26f13', 'newsletter.vantagem.4.texto', '{"pt":"Campanhas e condições só para subscritores, quando as houver.","en":"Campaigns and terms just for subscribers, whenever there are any.","es":"Campañas y condiciones solo para suscriptores, cuando las haya."}', 'Página da newsletter: texto da quarta vantagem. Não prometer o que a galeria ainda não decidiu.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('41d94ce2-e356-4f45-bfbb-e1f93c63ca7a', 'newsletter.pagina.subscrever', '{"pt":"DEIXE O SEU EMAIL.","en":"LEAVE YOUR EMAIL.","es":"DEJE SU EMAIL."}', 'Página da newsletter: título do bloco claro, ao lado do campo de email.', 'newsletter', 1793204051);
--> statement-breakpoint
INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('505fec58-6965-4e0b-b04a-e42104e9f1a0', 'newsletter.pagina.nota', '{"pt":"Só pedimos o email, e serve só para a newsletter. Cada mensagem traz no fim um link para cancelar a subscrição.","en":"We only ask for your email, and it is used only for the newsletter. Every message ends with a link to unsubscribe.","es":"Solo pedimos el email, y sirve solo para la newsletter. Cada mensaje lleva al final un enlace para cancelar la suscripción."}', 'Página da newsletter: frase ao lado do campo de email.', 'newsletter', 1793204051);
